import random

import pytest


def make_ids(n: int, seed: int) -> list[int]:
    """Return n distinct record ids, identical on every run for the same seed.

    Uses only a locally constructed, seeded generator. No global random
    state, no I/O, and no other capabilities are used.

    Raises ValueError if n is negative.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    rng = random.Random(seed)
    return rng.sample(range(1, 2**63), n)


def test_make_ids_length() -> None:
    assert len(make_ids(5, 0)) == 5


def test_make_ids_empty() -> None:
    assert make_ids(0, 42) == []


def test_make_ids_distinct() -> None:
    ids = make_ids(1000, 7)
    assert len(set(ids)) == 1000


def test_make_ids_deterministic() -> None:
    assert make_ids(50, 123) == make_ids(50, 123)


def test_make_ids_seed_changes_output() -> None:
    assert make_ids(50, 1) != make_ids(50, 2)


def test_make_ids_negative_raises() -> None:
    with pytest.raises(ValueError):
        make_ids(-1, 0)
